import json

schema = {"name": str, "age": int, "tags": list}

def validate(obj, schema):
    errors = []
    for key, typ in schema.items():
        if key not in obj:
            errors.append(f"thiếu '{key}'")
        elif not isinstance(obj[key], typ):
            errors.append(f"'{key}' phải là {typ.__name__}")
    return errors

def parse_llm_json(text):
    # Mô hình hay bọc JSON trong ```json ... ``` hoặc thêm lời dẫn
    start, end = text.find("{"), text.rfind("}")
    if start == -1 or end == -1:
        raise ValueError("không có JSON")
    return json.loads(text[start:end + 1])

raw = 'Đây là kết quả:\n```json\n{"name": "An", "age": "20", "tags": ["a"]}\n```'
obj = parse_llm_json(raw)
print(validate(obj, schema))                       # tuổi là chuỗi, sai kiểu

# Vòng thử lại: gửi lỗi trả cho mô hình (mô phỏng)
attempts = [raw, '{"name": "An", "age": 20, "tags": ["a"]}']
for i, a in enumerate(attempts, 1):
    errs = validate(parse_llm_json(a), schema)
    print("lần", i, "->", "OK" if not errs else errs)
    if not errs:
        break

